1. Identifies the frame color by verifying all border cells of its bounding box match that color
2. Extracts the frame pattern using min_r, min_c coordinates
3. Copies the pattern to position (0,0) in the result grid

```python
def transform(grid):
    rows, cols = len(grid), len(grid[0])
    if rows == 0: return grid

    frame_color = None

    colors = set(val for row in grid for val in row)
    for color in colors:
        coords = []
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == color:
                    coords.append((r, c))

        if not coords:
            continue

        min_r = min(r for r, c in coords)
        max_r = max(r for r, c in coords)
        min_c = min(c for r, c in coords)
        max_c = max(c for r, c in coords)

        h, w = max_r - min_r + 1, max_c - min_c + 1
        if h < 2 or w < 2:
            continue

        # Check if all border cells match the color
        is_frame = True
        for c in range(min_c, max_c + 1):
            if grid[min_r][c] != color or grid[max_r][c] != color:
                is_frame = False
                break
        if is_frame:
            for r in range(min_r, max_r + 1):
                if grid[r][min_c] != color or grid[r][max_c] != color:
                    is_frame = False
                    break

        if is_frame:
            frame_color = color
            min_r_frame, max_r_frame = min_r, max_r
            min_c_frame, max_c_frame = min_c, max_c
            break

    if frame_color is None:
        return grid

    # Extract frame pattern
    pattern = []
    for r in range(max_r_frame - min_r_frame + 1):
        row_pat = []
        for c in range(max_c_frame - min_c_frame + 1):
            row_pat.append(grid[min_r_frame + r][min_c_frame + c])
        pattern.append(row_pat)

    # Create result grid (copy of original)
    result = [row[:] for row in grid]

    # Copy pattern to (0,0)
    for r in range(len(pattern)):
        for c in range(len(pattern[0])):
            if 0 + r < rows and 0 + c < cols:
                result[r][c] = pattern[r][c]

    return result
